-- Game-aware catalog identities and media primitives.
--
-- This migration creates schema only. It does not import or modify either
-- production SQLite database. Surrogate IDs use GENERATED BY DEFAULT so a
-- future, audited migration can preserve legacy numeric IDs where applicable.
--
-- Important identity boundaries:
--   * cards are canonical game-level identities;
--   * printings are game-specific set/collector/language/variant instances;
--   * provider identifiers are stored separately from internal primary keys;
--   * illustrations exist independently of printings/faces so known illustration
--     IDs without a current card face can still be retained with their tag data;
--   * images and hashes are separate so a changed image URL never inherits a
--     hash computed from a different image resource.

CREATE TABLE catalog.sets (
    set_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    game_id TEXT NOT NULL,
    name TEXT NOT NULL,
    set_code TEXT,
    set_type TEXT,
    released_at DATE,
    metadata JSONB NOT NULL DEFAULT '{}'::JSONB,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT sets_game_fk
        FOREIGN KEY (game_id) REFERENCES catalog.games(game_id) ON DELETE RESTRICT,
    CONSTRAINT sets_name_nonempty CHECK (btrim(name) <> ''),
    CONSTRAINT sets_id_game_uq UNIQUE (set_id, game_id)
);

-- Set codes are only unique within a game. Null/blank codes remain allowed
-- for sets whose source does not supply a stable code.
CREATE UNIQUE INDEX catalog_sets_game_code_uq
    ON catalog.sets (game_id, lower(btrim(set_code)))
    WHERE set_code IS NOT NULL AND btrim(set_code) <> '';

CREATE INDEX catalog_sets_game_name_idx
    ON catalog.sets (game_id, lower(btrim(name)));

CREATE TABLE catalog.cards (
    card_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    game_id TEXT NOT NULL,
    name TEXT NOT NULL,
    normalized_name TEXT GENERATED ALWAYS AS (lower(btrim(name))) STORED,
    type_line TEXT,
    rules_text TEXT,
    metadata JSONB NOT NULL DEFAULT '{}'::JSONB,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT cards_game_fk
        FOREIGN KEY (game_id) REFERENCES catalog.games(game_id) ON DELETE RESTRICT,
    CONSTRAINT cards_name_nonempty CHECK (btrim(name) <> ''),
    CONSTRAINT cards_id_game_uq UNIQUE (card_id, game_id)
);

CREATE INDEX catalog_cards_game_name_idx
    ON catalog.cards (game_id, normalized_name);

CREATE TABLE catalog.illustrations (
    illustration_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    game_id TEXT NOT NULL,
    metadata JSONB NOT NULL DEFAULT '{}'::JSONB,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT illustrations_game_fk
        FOREIGN KEY (game_id) REFERENCES catalog.games(game_id) ON DELETE RESTRICT,
    CONSTRAINT illustrations_id_game_uq UNIQUE (illustration_id, game_id)
);

CREATE INDEX catalog_illustrations_game_idx
    ON catalog.illustrations (game_id, illustration_id);

CREATE TABLE catalog.images (
    image_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    game_id TEXT NOT NULL,
    provider_id TEXT NOT NULL,
    image_uri TEXT NOT NULL,
    image_role TEXT,
    media_type TEXT,
    width INTEGER,
    height INTEGER,
    metadata JSONB NOT NULL DEFAULT '{}'::JSONB,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT images_provider_fk
        FOREIGN KEY (game_id, provider_id)
        REFERENCES catalog.game_providers(game_id, provider_id) ON DELETE RESTRICT,
    CONSTRAINT images_uri_nonempty CHECK (btrim(image_uri) <> ''),
    CONSTRAINT images_width_positive CHECK (width IS NULL OR width > 0),
    CONSTRAINT images_height_positive CHECK (height IS NULL OR height > 0),
    CONSTRAINT images_id_game_uq UNIQUE (image_id, game_id),
    CONSTRAINT images_game_provider_uri_uq UNIQUE (game_id, provider_id, image_uri)
);

CREATE INDEX catalog_images_game_provider_idx
    ON catalog.images (game_id, provider_id);

CREATE TABLE catalog.image_hashes (
    image_id BIGINT NOT NULL,
    game_id TEXT NOT NULL,
    hash_algorithm TEXT NOT NULL,
    hash_version TEXT NOT NULL DEFAULT '1',
    hash_value TEXT NOT NULL,
    computed_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    metadata JSONB NOT NULL DEFAULT '{}'::JSONB,
    CONSTRAINT image_hashes_pk PRIMARY KEY (image_id, hash_algorithm, hash_version),
    CONSTRAINT image_hashes_image_fk
        FOREIGN KEY (image_id, game_id)
        REFERENCES catalog.images(image_id, game_id) ON DELETE CASCADE,
    CONSTRAINT image_hashes_algorithm_nonempty CHECK (btrim(hash_algorithm) <> ''),
    CONSTRAINT image_hashes_value_nonempty CHECK (btrim(hash_value) <> '')
);

CREATE INDEX catalog_image_hashes_lookup_idx
    ON catalog.image_hashes (hash_algorithm, hash_value);

CREATE TABLE catalog.printings (
    printing_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    game_id TEXT NOT NULL,
    card_id BIGINT,
    set_id BIGINT,
    collector_number TEXT,
    language_code TEXT,
    rarity TEXT,
    printing_variant TEXT,
    available_finishes TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],
    image_id BIGINT,
    released_at DATE,
    is_promo BOOLEAN,
    metadata JSONB NOT NULL DEFAULT '{}'::JSONB,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT printings_game_fk
        FOREIGN KEY (game_id) REFERENCES catalog.games(game_id) ON DELETE RESTRICT,
    CONSTRAINT printings_card_game_fk
        FOREIGN KEY (card_id, game_id)
        REFERENCES catalog.cards(card_id, game_id) ON DELETE RESTRICT,
    CONSTRAINT printings_set_game_fk
        FOREIGN KEY (set_id, game_id)
        REFERENCES catalog.sets(set_id, game_id) ON DELETE RESTRICT,
    CONSTRAINT printings_image_game_fk
        FOREIGN KEY (image_id, game_id)
        REFERENCES catalog.images(image_id, game_id) ON DELETE SET NULL,
    CONSTRAINT printings_id_game_uq UNIQUE (printing_id, game_id)
);

-- These are lookup indexes, not uniqueness constraints: some games and source
-- catalogs legitimately reuse collector numbers across variants or languages.
CREATE INDEX catalog_printings_game_card_idx
    ON catalog.printings (game_id, card_id)
    WHERE card_id IS NOT NULL;

CREATE INDEX catalog_printings_set_collector_idx
    ON catalog.printings (game_id, set_id, collector_number)
    WHERE set_id IS NOT NULL;

CREATE INDEX catalog_printings_game_collector_idx
    ON catalog.printings (game_id, lower(btrim(collector_number)))
    WHERE collector_number IS NOT NULL;

CREATE TABLE catalog.printing_faces (
    printing_id BIGINT NOT NULL,
    game_id TEXT NOT NULL,
    face_index INTEGER NOT NULL DEFAULT 0,
    name TEXT,
    type_line TEXT,
    rules_text TEXT,
    flavor_text TEXT,
    image_id BIGINT,
    illustration_id BIGINT,
    metadata JSONB NOT NULL DEFAULT '{}'::JSONB,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT printing_faces_pk PRIMARY KEY (printing_id, face_index),
    CONSTRAINT printing_faces_index_nonnegative CHECK (face_index >= 0),
    CONSTRAINT printing_faces_printing_game_fk
        FOREIGN KEY (printing_id, game_id)
        REFERENCES catalog.printings(printing_id, game_id) ON DELETE CASCADE,
    CONSTRAINT printing_faces_image_game_fk
        FOREIGN KEY (image_id, game_id)
        REFERENCES catalog.images(image_id, game_id) ON DELETE SET NULL,
    CONSTRAINT printing_faces_illustration_game_fk
        FOREIGN KEY (illustration_id, game_id)
        REFERENCES catalog.illustrations(illustration_id, game_id) ON DELETE SET NULL
);

CREATE INDEX catalog_printing_faces_game_illustration_idx
    ON catalog.printing_faces (game_id, illustration_id)
    WHERE illustration_id IS NOT NULL;

CREATE INDEX catalog_printing_faces_game_image_idx
    ON catalog.printing_faces (game_id, image_id)
    WHERE image_id IS NOT NULL;

-- A provider ID is never an internal primary key. One entity can have multiple
-- IDs from a provider, so external_id_type is retained explicitly (for example
-- Scryfall's oracle_id vs. scryfall_id).
CREATE TABLE catalog.external_ids (
    external_id_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    game_id TEXT NOT NULL,
    provider_id TEXT NOT NULL,
    entity_type TEXT NOT NULL,
    external_id_type TEXT NOT NULL,
    external_id TEXT NOT NULL,
    card_id BIGINT,
    printing_id BIGINT,
    set_id BIGINT,
    illustration_id BIGINT,
    metadata JSONB NOT NULL DEFAULT '{}'::JSONB,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT external_ids_provider_fk
        FOREIGN KEY (game_id, provider_id)
        REFERENCES catalog.game_providers(game_id, provider_id) ON DELETE RESTRICT,
    CONSTRAINT external_ids_entity_type_check
        CHECK (entity_type IN ('card', 'printing', 'set', 'illustration')),
    CONSTRAINT external_ids_target_matches_type CHECK (
        (entity_type = 'card' AND card_id IS NOT NULL
            AND num_nonnulls(printing_id, set_id, illustration_id) = 0)
        OR
        (entity_type = 'printing' AND printing_id IS NOT NULL
            AND num_nonnulls(card_id, set_id, illustration_id) = 0)
        OR
        (entity_type = 'set' AND set_id IS NOT NULL
            AND num_nonnulls(card_id, printing_id, illustration_id) = 0)
        OR
        (entity_type = 'illustration' AND illustration_id IS NOT NULL
            AND num_nonnulls(card_id, printing_id, set_id) = 0)
    ),
    CONSTRAINT external_ids_type_nonempty CHECK (btrim(external_id_type) <> ''),
    CONSTRAINT external_ids_value_nonempty CHECK (btrim(external_id) <> ''),
    CONSTRAINT external_ids_card_game_fk
        FOREIGN KEY (card_id, game_id)
        REFERENCES catalog.cards(card_id, game_id) ON DELETE CASCADE,
    CONSTRAINT external_ids_printing_game_fk
        FOREIGN KEY (printing_id, game_id)
        REFERENCES catalog.printings(printing_id, game_id) ON DELETE CASCADE,
    CONSTRAINT external_ids_set_game_fk
        FOREIGN KEY (set_id, game_id)
        REFERENCES catalog.sets(set_id, game_id) ON DELETE CASCADE,
    CONSTRAINT external_ids_illustration_game_fk
        FOREIGN KEY (illustration_id, game_id)
        REFERENCES catalog.illustrations(illustration_id, game_id) ON DELETE CASCADE,
    CONSTRAINT external_ids_provider_entity_uq
        UNIQUE (game_id, provider_id, entity_type, external_id_type, external_id)
);

CREATE INDEX catalog_external_ids_card_idx
    ON catalog.external_ids (game_id, card_id)
    WHERE card_id IS NOT NULL;

CREATE INDEX catalog_external_ids_printing_idx
    ON catalog.external_ids (game_id, printing_id)
    WHERE printing_id IS NOT NULL;

CREATE INDEX catalog_external_ids_set_idx
    ON catalog.external_ids (game_id, set_id)
    WHERE set_id IS NOT NULL;

CREATE INDEX catalog_external_ids_illustration_idx
    ON catalog.external_ids (game_id, illustration_id)
    WHERE illustration_id IS NOT NULL;

COMMENT ON TABLE catalog.cards IS
    'Canonical game-level card identities. Provider-specific IDs live in catalog.external_ids.';

COMMENT ON TABLE catalog.printings IS
    'A game-specific printing. Card/set relationships are optional and game-scoped; collector numbers remain text.';

COMMENT ON TABLE catalog.illustrations IS
    'Artwork identities independent of printings and faces; rows may exist before or without a known printing face.';

COMMENT ON TABLE catalog.images IS
    'Provider-sourced image resources. A changed URI is a distinct image resource.';

COMMENT ON TABLE catalog.image_hashes IS
    'Recognition hashes belong to a specific image resource and algorithm/version.';

COMMENT ON TABLE catalog.external_ids IS
    'Provider-scoped external identifiers mapped to exactly one game-scoped catalog entity.';
